-- Brazil deep-dive content: page, stats, file_format cards,
-- scope_transmission cards + lifecycle card ("The NF-e clearance flow"),
-- steps, penalties_related cards, portal. No penalty rows/table.

INSERT OR IGNORE INTO deep_dive_pages (country_id, last_updated) SELECT id, '2026-07-21' FROM countries WHERE name_en = 'Brazil';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro) SELECT id, 'en', 'Multi-layered clearance (state + municipal + federal)', 'This deep-dive page reflects publicly available technical guidance as of July 2026 and is provided for general awareness, not legal or tax advice. Technical Note 2025.002-RTC continues to be revised through the tax reform transition, and state/municipal requirements vary — confirm current requirements directly with SEFAZ, the Receita Federal, or a Brazilian tax advisor before building an integration.', 'Brazil''s NF-e system has run since the mid-2000s with near-universal adoption — the live story today is the consumption tax reform being layered into the existing infrastructure.', 'Brazil''s XML depth is genuinely unusual — this is a far more granular structure than most European e-invoicing standards.', 'Brazil doesn''t run one e-invoicing system — it runs several, split by transaction type and level of government, each with its own quirks.', 'Because the tax reform sits on top of a mature existing system, "getting ready" here mostly means upgrading what you already run, not building from scratch.', 'In Brazil, rejection is often the sharper practical risk — a blocked invoice halts the movement of goods, which frequently matters more than the fine itself.' FROM countries WHERE name_en = 'Brazil';

