INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 0 FROM countries WHERE name_en = 'Brazil';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Document structure', '[["Legal document", "The signed XML — not the printed DANFE"], ["Structure depth", "500+ structured tags, 400+ validation rules"], ["Model codes", "Model 55 (NF-e), Model 65 (NFC-e)"]]', 'The DANFE contains less than 10% of the XML''s data — treat any AP process that only reads the DANFE as manually re-keying information that already exists in structured form, and likely missing tax detail that affects input credit recovery.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Brazil' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 1 FROM countries WHERE name_en = 'Brazil';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'The 44-digit access key', '[["Name", "Chave de acesso"], ["Scope", "Unique across all of Brazil, across all time"], ["Governing spec", "SEFAZ Nota Técnica 2011/004"]]', 'This single key is all you need to verify an NF-e''s authenticity, check whether it''s been cancelled, or retrieve the full XML directly from SEFAZ — treat it as the universal reference for any Brazilian invoice.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Brazil' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 2 FROM countries WHERE name_en = 'Brazil';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'Digital signature', '[["Certificate types", "A1 (software-based) or A3 (hardware token)"], ["Accreditation", "ICP-Brasil-accredited certificate authority"]]', 'Both certificate types are valid — A1 suits automated high-volume issuance, A3 suits lower-volume or higher-security scenarios, but confirm which your specific ERP integration supports.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Brazil' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'file_format', 3 FROM countries WHERE name_en = 'Brazil';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'New tax reform fields (NT 2025.002-RTC)', '[["New groups", "IBS, CBS, and IS (Selective Tax) data groups"], ["New tax codes", "CST codes specific to the three new taxes"], ["New document types", "Formal Debit Notes and Credit Notes within model 55"]]', 'Debit and Credit Notes are a genuinely new instrument, not a repurposed old one — but they explicitly cannot be used to adjust legacy ICMS or IPI unless that legislation is separately amended.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Brazil' AND dc.section = 'file_format' AND dc.sort_order = 3;

INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 0 FROM countries WHERE name_en = 'Brazil';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'The document family', '[["NF-e", "Goods — state-level SEFAZ"], ["NFC-e", "Retail/consumer receipts — state-level SEFAZ"], ["CT-e", "Transport documents — state-level SEFAZ"], ["NFS-e", "Services — municipal level (5,000+ variations)"]]', 'Which system applies depends entirely on what you''re invoicing — goods, transport, and retail sit with the state; services sit with the municipality, and municipal requirements vary significantly.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Brazil' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 1 FROM countries WHERE name_en = 'Brazil';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'NFS-e fragmentation, and the fix underway', '[["Current state", "Each Prefeitura (municipality) sets its own requirements"], ["National standard", "SNNFS-e (Sistema Nacional da Nota Fiscal de Serviços Eletrônica)"], ["Components", "Centralized submission portal + NDE (National Data Environment) repository"]]', 'SNNFS-e adoption is gradual and not yet mandatory everywhere — check your specific municipality''s current status rather than assuming national standardisation has already happened.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Brazil' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'scope_transmission', 2 FROM countries WHERE name_en = 'Brazil';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', 'What''s coming: Split Payment', '[["Legal basis", "Joint Administrative Act RFB/CGIBS No. 2/2026"], ["What it does", "Publishes technical documentation for a Public Split Payment Platform"]]', 'This is an emerging piece of the reform architecture — automatic tax remittance at the point of payment — worth tracking even though it''s not yet a live obligation.', NULL, NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Brazil' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;

