INSERT OR IGNORE INTO deep_dive_steps (country_id, sort_order) SELECT id, 0 FROM countries WHERE name_en = 'Brazil';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'en', 'Obtain an ICP-Brasil digital certificate', 'Choose A1 or A3 depending on your volume and infrastructure, from an accredited certificate authority — this is required before you can sign a single NF-e.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Brazil' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_steps (country_id, sort_order) SELECT id, 1 FROM countries WHERE name_en = 'Brazil';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'en', 'Configure your fiscal establishment setup', 'Set up certificate, environment, NF-e version, authority, schema validation, and contingency mode per fiscal establishment in your ERP — this is genuinely per-establishment configuration, not a one-time global setting.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Brazil' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_steps (country_id, sort_order) SELECT id, 2 FROM countries WHERE name_en = 'Brazil';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'en', 'Update to Technical Note 2025.002-RTC (current version)', 'Map the new IBS, CBS, and IS fields and updated CST tax codes into your invoicing layouts — check the version number carefully, as this note has been revised multiple times through 2025–2026.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Brazil' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_steps (country_id, sort_order) SELECT id, 3 FROM countries WHERE name_en = 'Brazil';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'en', 'Test in SEFAZ''s homologation environment', 'Use the same certificates as production, pointed at test servers, to validate your new tax-reform fields before they affect real invoices.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Brazil' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_steps (country_id, sort_order) SELECT id, 4 FROM countries WHERE name_en = 'Brazil';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'en', 'Build the new Debit/Credit Note workflows', 'Implement the formalised model-55 Debit and Credit Note instruments for CBS/IBS adjustments — remembering they can''t be used for legacy ICMS/IPI corrections without separate legislative change.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Brazil' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_steps (country_id, sort_order) SELECT id, 5 FROM countries WHERE name_en = 'Brazil';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'en', 'Check your NFS-e municipality''s specific requirements', 'If you issue service invoices, confirm your municipality''s current NFS-e specification and SNNFS-e adoption status separately — don''t assume national uniformity yet.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Brazil' AND ds.sort_order = 5;
INSERT OR IGNORE INTO deep_dive_steps (country_id, sort_order) SELECT id, 6 FROM countries WHERE name_en = 'Brazil';
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'en', 'Confirm your regime''s transition timeline', 'Simples Nacional and MEI businesses generally have an extended transition (through 2027) compared to Normal/General Tax Regime taxpayers — verify which applies to you before assuming the same deadlines.' FROM deep_dive_steps ds JOIN countries co ON co.id = ds.country_id WHERE co.name_en = 'Brazil' AND ds.sort_order = 6;

INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 0 FROM countries WHERE name_en = 'Brazil';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', '🚧 Rejection as operational penalty', NULL, NULL, 'From 3 August 2026, missing or inconsistent IBS/CBS data risks outright document rejection in production — a rejected NF-e cannot be used to ship goods, making this a supply-chain disruption risk as much as a compliance one.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Brazil' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 1 FROM countries WHERE name_en = 'Brazil';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', '🌱 The soft-landing was informal, not legal exemption', NULL, NULL, 'Even during the January–April 2026 grace period where missing IBS/CBS fields didn''t trigger rejection, the underlying legal requirement to include that data was already in force — companies that skipped it entirely still face penalty exposure retroactively.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Brazil' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 2 FROM countries WHERE name_en = 'Brazil';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', '🏛️ State-level variation adds complexity', NULL, NULL, 'Individual states can layer their own technical mandates on top of the federal framework — Goiás, for example, separately requires ICMS taxpayers to integrate payment systems (cards, PIX) directly with NF-e/NFC-e issuance in real time.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Brazil' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_cards (country_id, section, sort_order) SELECT id, 'penalties_related', 3 FROM countries WHERE name_en = 'Brazil';
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body, badge_label, badge_type) SELECT dc.id, 'en', '🌍 Foreign suppliers newly in scope', NULL, NULL, 'The reform extends CBS/IBS obligations to foreign digital service providers for the first time — previously, foreign suppliers generally couldn''t register without a local presence, and cross-border digital services often fell under municipal ISS instead.', NULL, NULL FROM deep_dive_cards dc JOIN countries co ON co.id = dc.country_id WHERE co.name_en = 'Brazil' AND dc.section = 'penalties_related' AND dc.sort_order = 3;

